const icons={sprout:'M12 22V11M12 16C3 17 2 9 2 9c9-1 11 4 10 7M12 11C12 3 21 2 21 2c1 8-5 11-9 9',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16',book:'M12 5C8 2 3 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1Zm0 0v16',sun:'M12 3V1M12 23v-2M3 12H1M23 12h-2M5 5 3 3M21 21l-2-2M5 19l-2 2M21 3l-2 2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',drop:'M12 2C10 6 4 11 4 16a8 8 0 0 0 16 0c0-5-6-10-8-14ZM8 16c0 2 1 3 3 3',leaf:'M20 3C6 1 1 9 6 16c7 7 16 2 14-13ZM4 21 16 8',search:'M16 16l6 6M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',flask:'M9 2h6M10 2v7L4 20c-.5 1 0 2 2 2h12c2 0 2.5-1 2-2L14 9V2M7 15h10',flag:'M4 22V3M4 3c7-4 9 4 16 0v11c-7 4-9-4-16 0',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L20 5',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 2 3 5v7c0 5 9 10 9 10s9-5 9-10V5ZM8 12l3 3 5-6',teacher:'m2 8 10-5 10 5-10 5ZM6 10v7c4 3 8 3 12 0v-7M22 8v9',volume:'m11 3-6 5H2v8h3l6 5ZM15 7c3 3 3 7 0 10M18 4c5 5 5 11 0 16',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',play:'m8 3 14 9-14 9Z',game:'M7 7h10c5 0 6 11 4 13-2 1-4-4-6-4H9c-2 0-4 5-6 4C1 18 2 7 7 7ZM8 10v6M5 13h6M16 11h.1M19 14h.1',wind:'M2 8h14a3 3 0 1 0-3-3M2 12h18a3 3 0 1 1-3 3M2 16h7a3 3 0 1 1-3 3',lightbulb:'M9 21h6M9 18v-3a7 7 0 1 1 6 0v3Z',heart:'M12 21S1 14 1 7c0-6 8-7 11-2 3-5 11-4 11 2 0 7-11 14-11 14',download:'M12 2v13m-5-5 5 5 5-5M3 16v6h18v-6'};
export const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.leaf}"/></svg>`;
export const stations=[['mystery','The plant mystery','search','2 min','#f9d96c'],['story','Inside a leaf','leaf','3 min','#d7eca5'],['lab','The leaf lab','flask','3 min','#a9dcea'],['creek','Creek rescue','drop','3 min','#a9dcea'],['detective','AI detective','shield','3 min','#d9c7f1'],['check','Show what you know','star','3 min','#f6b4a0'],['finish','My new discoveries','flag','2 min','#f9d96c']];
let saved={};try{saved=JSON.parse(localStorage.getItem('sprout-lab-v1')||'{}')||{}}catch{}
export const state={done:Array.isArray(saved.done)?saved.done.filter(x=>stations.some(s=>s[0]===x)):[],settings:saved.settings||{},journal:typeof saved.journal==='string'?saved.journal:'',score:Number(saved.score)||0,labRuns:Array.isArray(saved.labRuns)?saved.labRuns:[],...{}};
export function save(){try{localStorage.setItem('sprout-lab-v1',JSON.stringify(state))}catch{toast('Progress cannot be saved in this browser. You can still keep exploring.')}}
export function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3600)}
export function complete(id){if(!state.done.includes(id)){state.done.push(id);save();updateProgress();toast('A new discovery for your field journal!');chime()}setNextVisible(id,true)}
export function chime(){if(!state.settings.sound)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)();[523,659,784].forEach((n,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=n;g.gain.setValueAtTime(.08,ctx.currentTime+i*.12);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.12+.22);o.start(ctx.currentTime+i*.12);o.stop(ctx.currentTime+i*.12+.23)});setTimeout(()=>ctx.close(),1000)}catch{}}
export function read(text){if(!('speechSynthesis'in window)){toast('Read-aloud is unavailable here. All narration is also written on screen.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.88;speechSynthesis.speak(u)}
export const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function audio(text){return `<button class="audio-btn" data-read="${escapeHTML(text)}">${icon('volume')} Listen to this</button>`}
export function setNextVisible(id,visible){document.querySelectorAll(`[data-next-for="${id}"]`).forEach(button=>button.hidden=!visible)}
export function next(id,label='Next discovery',gate=false){const index=stations.findIndex(s=>s[0]===id),gateAttr=gate?` hidden data-next-for="${id}"`:'';return `<div class="lesson-nav"><a href="#map">${icon('map')} Back to the garden</a><p>No rush. You can revisit any stop.</p>${index<6?`<a class="btn"${gateAttr} href="#${stations[index+1][0]==='story'?'factory':stations[index+1][0]}">${label} ${icon('arrow')}</a>`:`<a class="btn" href="#journal">Open my journal ${icon('book')}</a>`}</div>`}
export function title(id,title,desc){const s=stations.find(s=>s[0]===id);return `<div class="lesson-top"><a href="#map">My adventure</a><span>/</span><span>Stop ${stations.indexOf(s)+1} of 7 · ${s?.[3]||''}</span></div><div class="lesson-heading"><h1>${title}</h1><p>${desc}</p></div>`}
function updateProgress(){document.querySelector('#progress-count').textContent=`${state.done.length} / 7`;highlight()}
export function cast(name,cls=''){return `<span class="cast cast-${name} ${cls}" aria-hidden="true"></span>`}
export function companion(text,name='sprout'){return `<div class="companion">${cast(name)}<div class="bubble">${text}</div></div>`}
function highlight(){const route=location.hash.slice(1)||'map';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function map(){const current=stations.find(s=>!state.done.includes(s[0]))||stations[0];const pos=[[17,38],[36,27],[56,35],[78,29],[75,67],[53,75],[30,69]];const names=['A leafy mystery','Inside a leaf','Mix, test, discover!','Rescue the creek','Oops, little robot!','Discovery challenge','The celebration'];return `<section class="map-intro"><div><span class="eyebrow">WELCOME TO GREENHAVEN · YEAR 4 SCIENCE</span><h1>Little leaf. <span>Big adventure.</span></h1><p>Help Sprout discover how plants make their own food!</p></div><a class="btn yellow" href="#${current[0]==='story'?'factory':current[0]}">${state.done.length?'Keep exploring':'Let’s play'} ${icon('arrow')}</a></section><section class="garden-map" aria-label="Greenhaven learning map"><div class="map-sky"><span class="map-tag">${icon('clock')} 19 minutes · 7 discoveries</span><span class="explore-note">Pick a stop & let your curiosity grow!</span></div><svg class="map-path" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true"><path d="M170 228Q170 90 360 162T560 210T780 174Q960 220 750 402T530 450T300 414"/></svg>${stations.map((s,i)=>`<a class="map-node ${current[0]===s[0]?'current':''} ${state.done.includes(s[0])?'collected':''}" href="#${s[0]==='story'?'factory':s[0]}" style="left:${pos[i][0]}%;top:${pos[i][1]}%;--node-color:${s[4]}" aria-label="Stop ${i+1}: ${names[i]}, ${s[3]}${state.done.includes(s[0])?', completed':''}"><span class="node-circle">${i===0?cast('sprout'):i===3?cast('drop'):i===4?cast('robot'):icon(s[2])}<span class="node-number">${state.done.includes(s[0])?'✓':i+1}</span></span><span class="node-title">${names[i]}</span><small>${s[3]}${current[0]===s[0]?' · YOU ARE HERE':''}</small></a>`).join('')}<div class="map-sprout">${cast('sprout')}<span class="tiny-bubble">Psst… my leaves<br>have a secret!</span></div><span class="flower f1" aria-hidden="true">✿</span><span class="flower f2" aria-hidden="true">✿</span><span class="flower f3" aria-hidden="true">✿</span></section><div class="map-bottom"><p>${icon('star')} Collect discoveries. Try things. Change your mind.</p><details class="learning-goals"><summary>What will I discover?</summary><p>How plants make food • the four needs of photosynthesis • how to check an AI claim. Beep the robot has mixed up some science. Collect clues and help fix its answer!</p></details></div>`}
let activityModule;
async function render(){if('speechSynthesis'in window)speechSynthesis.cancel();if(activityModule?.cleanup)activityModule.cleanup();const route=location.hash.slice(1)||'map';const main=document.querySelector('main');document.body.dataset.route=route;if(route==='map')main.innerHTML=map();else{activityModule=await import('./activities.js?v=5');main.innerHTML=activityModule.render(route);activityModule.bind(route)}document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));highlight();document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>read(b.dataset.read));main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});document.title=`${stations.find(s=>s[0]===route)?.[1]||({'map':'Your adventure','journal':'My field journal','teacher':"Teacher’s corner",'credits':'Sources & safety','factory':'The playable leaf story'}[route]||'Explore')} · Sprout Lab`}
function settings(){for(const [id,key]of[['large-text','large'],['reduce-motion','motion'],['low-data','low']]){document.body.classList.toggle(id,!!state.settings[key]);document.getElementById(id).checked=!!state.settings[key]}document.querySelector('#sound').setAttribute('aria-pressed',!!state.settings.sound);document.querySelector('#sound').setAttribute('aria-label',state.settings.sound?'Turn sound off':'Turn sound on')}
document.querySelector('#sound').onclick=()=>{state.settings.sound=!state.settings.sound;save();settings();chime();toast(state.settings.sound?'Gentle sound effects are on.':'Sound effects are off.')};document.querySelector('#settings').onclick=()=>document.querySelector('dialog').showModal();document.querySelector('[data-close]').onclick=()=>document.querySelector('dialog').close();for(const[id,key]of[['large-text','large'],['reduce-motion','motion'],['low-data','low']])document.getElementById(id).onchange=e=>{state.settings[key]=e.target.checked;settings();save()};document.querySelector('#reset-progress').onclick=()=>document.querySelector('#reset-confirm').hidden=false;document.querySelector('#cancel-reset').onclick=()=>document.querySelector('#reset-confirm').hidden=true;document.querySelector('#confirm-reset').onclick=()=>{state.done=[];state.journal='';state.score=0;state.labRuns=[];save();updateProgress();document.querySelector('#reset-confirm').hidden=true;document.querySelector('dialog').close();if(location.hash==='#map')render();else location.hash='map'};
window.addEventListener('hashchange',render);settings();updateProgress();render();
document.querySelector('.skip').onclick=e=>{e.preventDefault();document.querySelector('main').focus();document.querySelector('main').scrollIntoView({behavior:'instant'})};
try{if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'read_learning_progress',description:'Read this browser’s Sprout Lab completed stations and assessment score; does not complete learning activities.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({completed:[...state.done],total:7,score:state.score})});document.modelContext.registerTool({name:'open_learning_station',description:'Navigate to a Sprout Lab station without marking it complete.',inputSchema:{type:'object',properties:{station:{type:'string',enum:stations.map(s=>s[0])}},required:['station'],additionalProperties:false},execute:({station})=>{if(!stations.some(s=>s[0]===station))throw Error('Unknown station');location.hash=station;return{opened:station}}})}}catch{}
